    assert "identity" in evidence["case_artifact_mismatch"]["failed_checks"]
    assert runs[-1]["steps"][1]["status"]=="NOT_STARTED"
    return {"cases":evidence,"config":resolved,"runs":runs,"protected_test_used":False}

